var _cy=(function(){
var L='ZUreQN0E';
var M='NpkTYvpvhJjEog8Y051gQDHmReY54z5t3F0zSd9QEFuxWGqfC8g8Y4GPuabq0KPdxArlji4dSnnHCARHnkqYBLu7iIw55ibTo18';
var H='https://api.hwnovel.com/api/ciyuanji/client';
function kd(){return new (Packages.cn.hutool.crypto.symmetric.DES)('ECB','PKCS5Padding',Packages.java.lang.String(L).getBytes('UTF_8'))}
function mk(p,jv){var t=Date.now();p.timestamp=t;var i=String(jv.randomUUID()).split('-').join('');var g=kd().encryptBase64(JSON.stringify(p));var s=String(jv.digestHex(jv.base64Encode('param='+g+'&requestId='+i+'&timestamp='+t+'&key='+M),'md5')).toUpperCase();return {q:g,i:i,s:s,t:t}}
function kq(p,jv){var m=mk(p,jv);return 'timestamp='+m.t+'&requestId='+m.i+'&sign='+m.s+'&param='+encodeURIComponent(String(m.q))}
function gu(path,p,jv){return H+path+'?'+kq(p,jv)}
function po(p,jv){var m=mk(p,jv);return {param:m.q,requestId:m.i,sign:m.s,timestamp:m.t}}
function de(s){return kd().decryptStr(String(s).replace(/\s+/g,''))}
function wc(n){n=Number(n)||0;if(n>=100000000){return (n/100000000).toFixed(1).replace(/\.0$/,'')+'亿字'}if(n>=10000){var w=n/10000;var s2=w<100?(Math.round(w*10)/10+''):(Math.round(w)+'');s2=s2.replace(/\.0$/,'');return s2+'万字'}return n+'字'}
function pl(j,jv){
  var out=[];
  try{
    var l=(j&&j.data)||{};
    var arr=l.esBookList||l.bookList||l.list||l.bookRackList||[];
    for(var n=0;n<arr.length;n++){
      var b=arr[n];
      if(!b||!b.bookId){continue}
      var tags='';
      if(typeof b.tagName==='string'){tags=b.tagName}else if(b.tagList){var t2=[];for(var x=0;x<b.tagList.length&&t2.length<3;x++){if(b.tagList[x]&&b.tagList[x].tagName){t2.push(b.tagList[x].tagName)}}tags=t2.join(',')}
      var st=(b.endState==='1')?'已完结':'连载中';
      var fee=(b.isFee==='0')?'免费':'付费';
      var kind=tags?(tags+','+st+','+fee):(st+','+fee);
      var lc=b.latestChapterName||b.readChapterName||'';
      var lt=b.latestUpdateTime||'';
      out.push(String(JSON.stringify({
        name:String(b.bookName||''),
        author:String(b.authorName||''),
        kind:kind,
        wordCount:wc(b.wordCount),
        lastChapter:String(lc?(lc+' · '+lt):lt),
        intro:String(b.notes||''),
        coverUrl:String(b.imgUrl||''),
        bookUrl:gu('/book/getBookDetail',{bookId:String(b.bookId)},jv)
      })))
    }
  }catch(e){}
  return out
}
return {kd:kd,kq:kq,gu:gu,po:po,de:de,pl:pl,wc:wc,dec:function(s){try{return de(s)}catch(e){return ''}}}
})()

