var cyTip=function(s){java.longToast(String(s||''))};
function cySend(){
try{
var m=source.getLoginInfoMap();
var ph=String(m.get('手机号')||'');
if(ph.length<11){cyTip('请输入11位手机号');return}
var res=String(java.ajax('https://api.hwnovel.com/api/ciyuanji/client/login/getPhoneCode,'+JSON.stringify({method:'POST',body:JSON.stringify(_cy.po({phone:ph,smsType:'1'},java))})));
var r={};try{r=JSON.parse(res)}catch(e){}
if(r.code==='200'){cyTip('验证码已发送,请查收短信')}else{cyTip('发送失败: '+String(r.msg||res))}
}catch(e){cyTip('发送验证码出错: '+String(e.message||e))}
}
function cyLogin(){
try{
var m=source.getLoginInfoMap();
var ph=String(m.get('手机号')||'');
var cd=String(m.get('验证码')||'');
if(ph.length<11){cyTip('请输入11位手机号');return}
if(!cd){cyTip('请输入验证码');return}
var res=String(java.ajax('https://api.hwnovel.com/api/ciyuanji/client/login/phone,'+JSON.stringify({method:'POST',body:JSON.stringify(_cy.po({phone:ph,phoneCode:cd},java))})));
var r={};try{r=JSON.parse(res)}catch(e){}
if(r.code==='200'){
  var tkn=(r.data&&r.data.userInfo&&r.data.userInfo.token)||'';
  var nm=(r.data&&r.data.userInfo&&r.data.userInfo.cmUser&&r.data.userInfo.cmUser.nickName)||'';
  if(tkn){try{source.putLoginHeader(JSON.stringify({token:tkn}))}catch(e){};cyTip('登录成功! '+String(nm))}else{cyTip('登录响应缺少token,请重试')}
}else{cyTip('登录失败: '+String(r.msg||res))}
}catch(e){cyTip('登录出错: '+String(e.message||e))}
}
function cyCheck(){
try{
var res=String(java.ajax(_cy.gu('/user/getUserInfo',{},java)));
var r={};try{r=JSON.parse(res)}catch(e){}
if(r.code==='200'){
  var u=(r.data&&r.data.cmUser)||{};
