ruleContent.content:
@js:
(function(){
var j;
try{j=JSON.parse(String(result))}catch(e){throw new Error('正文接口异常,请重试')}
if(j.code!=='200'&&j.code!=='101'){throw new Error(String(j.msg||'获取正文失败'))}
var c=(j.data&&j.data.chapter)||null;
if(!c){throw new Error('章节不存在')}
var txt='';
try{txt=_cy.de(String(c.content||''))}catch(e){txt=''}
if(!txt){throw new Error('本章内容为空或获取失败')}
var arr=txt.split(String.fromCharCode(10));
var lines=[];
var imgs=(c.imgList)||[];
for(var i=0;i<arr.length;i++){
  lines.push(arr[i]);
  for(var k=0;k<imgs.length;k++){
    if(imgs[k]&&imgs[k].paragraphIndex===i){
      lines.push('<img src='+String.fromCharCode(34)+String(imgs[k].imgUrl||'')+String.fromCharCode(34)+'>')
    }
  }
}
if(j.code==='101'){
  lines.push('');
  lines.push('————————');
  lines.push('本章为VIP章节,当前为免费预览部分。');
  lines.push('点击右下角菜单「购买本章」,或在登录界面登录后购买,再重新进入本章即可阅读全文。')
}
return lines.join(String.fromCharCode(10))
})()

