@js:
(function(){
var u=String(chapter.url);
var m=u.match(/param=([^&$]+)/);
if(!m){java.longToast('无法解析章节参数');return}
var raw='';
try{raw=decodeURIComponent(m[1])}catch(e){raw=m[1]}
var pstr='';
try{pstr=_cy.de(raw)}catch(e){java.longToast('章节参数解密失败');return}
var p;
try{p=JSON.parse(pstr)}catch(e){java.longToast('章节参数解析失败');return}
var bookId=String(p.bookId||'');
var chapterId=String(p.chapterId||'');
if(!bookId||!chapterId){java.longToast('章节参数不完整');return}
var res='';
try{res=String(java.ajax('https://api.hwnovel.com/api/ciyuanji/client/order/consume,'+JSON.stringify({method:'POST',body:JSON.stringify(_cy.po({viewType:'2',consumeType:'1',bookId:bookId,productId:chapterId,buyCount:'1'},java))})))}catch(e){java.longToast('购买请求失败: '+String(e.message||e));return}
var rr={};
try{rr=JSON.parse(res)}catch(e){rr={msg:res}}
if(rr.code==='200'){java.longToast('✅ 购买成功!重新进入本章即可阅读全文')}
else if(String(rr.msg||'').indexOf('暂无可购买章节')>-1){java.longToast('本章无需购买(可能已购买,下拉刷新试试)')}
else{java.longToast('购买失败: '+String(rr.msg||res))}
})()
